import { Box, Group, Stack, Text } from '@mantine/core'
import DriveAssignmentField from './DriveAssignmentField'
import TruncatedText from './TruncatedText'
import FileList from './FileList'
import { LocalFile, LocalFileGroup } from './useFileTree'
import { DriveAssignment, DriveAssignmentsHandle, PickerTarget } from './useDriveAssignments'

const INDENT_PER_LEVEL = 16

interface Props {
  group: LocalFileGroup
  groupKey: string
  collapsedGroups: Set<string>
  onToggle: (groupKey: string) => void
  assignments: DriveAssignmentsHandle
  inheritedAssignment: DriveAssignment | null
  onPick: (target: PickerTarget) => void
  selectedPath: string | null
  onSelectFile: (file: LocalFile) => void
}

export default function GroupNode({ group, groupKey, collapsedGroups, onToggle, assignments, inheritedAssignment, onPick, selectedPath, onSelectFile }: Props) {
  const expanded = !collapsedGroups.has(groupKey)
  const own = assignments.groupAssignments.get(groupKey) ?? null
  const effective = own ?? inheritedAssignment

  return (
    <Box>
      <Group gap={8} wrap="nowrap" align="center">
        <button
          type="button"
          onClick={() => onToggle(groupKey)}
          aria-expanded={expanded}
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: 6,
            flex: 1,
            minWidth: 0,
            border: 'none',
            background: 'transparent',
            padding: 0,
            cursor: 'pointer',
            textAlign: 'left',
            fontFamily: 'inherit',
          }}
        >
          <Text size="xs" c="dimmed" style={{ width: 10, flexShrink: 0 }}>{expanded ? '▼' : '▶'}</Text>
          <TruncatedText label={group.name} size="sm" fw={600}>📁 {group.name}</TruncatedText>
        </button>
        <DriveAssignmentField
          label={group.name}
          assignment={effective}
          isOwn={own !== null}
          onPick={() => onPick({ type: 'group', key: groupKey })}
          onClear={() => assignments.clearGroupAssignment(groupKey)}
        />
      </Group>
      {expanded && (
        <Box pl={INDENT_PER_LEVEL}>
          <FileList
            files={group.files}
            assignments={assignments}
            inheritedAssignment={effective}
            onPick={onPick}
            selectedPath={selectedPath}
            onSelectFile={onSelectFile}
          />
          {group.subgroups.length > 0 && (
            <Stack gap={8} mt={4}>
              {group.subgroups.map(sub => (
                <GroupNode
                  key={sub.name}
                  group={sub}
                  groupKey={`${groupKey}/${sub.name}`}
                  collapsedGroups={collapsedGroups}
                  onToggle={onToggle}
                  assignments={assignments}
                  inheritedAssignment={effective}
                  onPick={onPick}
                  selectedPath={selectedPath}
                  onSelectFile={onSelectFile}
                />
              ))}
            </Stack>
          )}
        </Box>
      )}
    </Box>
  )
}

import { describe, it, expect, vi } from 'vitest'
import { act, renderHook, waitFor } from '@testing-library/react'
import { useFileTree } from './useFileTree'
import { PickFolder, ScanLocalRoot } from '../../../wailsjs/go/main/App'

vi.mock('../../../wailsjs/go/main/App', () => ({
  PickFolder: vi.fn(),
  ScanLocalRoot: vi.fn(),
}))

describe('useFileTree', () => {
  it('starts with no root and no tree', () => {
    const { result } = renderHook(() => useFileTree())
    expect(result.current.root).toBeNull()
    expect(result.current.tree).toBeNull()
    expect(result.current.loading).toBe(false)
    expect(result.current.error).toBeNull()
  })

  it('does nothing when the folder picker is cancelled', async () => {
    vi.mocked(PickFolder).mockResolvedValueOnce('')
    const { result } = renderHook(() => useFileTree())
    await act(async () => { await result.current.pickRoot() })
    expect(result.current.root).toBeNull()
    expect(ScanLocalRoot).not.toHaveBeenCalled()
  })

  it('scans the chosen root and stores the resulting tree', async () => {
    vi.mocked(PickFolder).mockResolvedValueOnce('/output/batch')
    const tree = {
      name: '',
      files: [],
      subgroups: [{ name: 'invoices', files: [{ path: '/output/batch/invoices/a.pdf', name: 'a', sizeBytes: 100, pageCount: 2, corrupt: false }], subgroups: [] }],
    }
    vi.mocked(ScanLocalRoot).mockResolvedValueOnce(tree as any)

    const { result } = renderHook(() => useFileTree())
    await act(async () => { await result.current.pickRoot() })

    expect(result.current.root).toBe('/output/batch')
    expect(result.current.tree).toEqual(tree)
    expect(result.current.loading).toBe(false)
    expect(result.current.error).toBeNull()
  })

  it('sets an error and clears the tree when the scan fails', async () => {
    vi.mocked(PickFolder).mockResolvedValueOnce('/output/batch')
    vi.mocked(ScanLocalRoot).mockRejectedValueOnce(new Error('permission denied'))

    const { result } = renderHook(() => useFileTree())
    await act(async () => { await result.current.pickRoot() })

    await waitFor(() => expect(result.current.error).toContain('permission denied'))
    expect(result.current.tree).toBeNull()
    expect(result.current.loading).toBe(false)
  })
})

