import { describe, it, expect, vi, beforeEach } from 'vitest'
import { act, renderHook, waitFor } from '@testing-library/react'
import { useUploadQueue, UploadTask } from './useUploadQueue'
import { UploadFile } from '../../../wailsjs/go/main/App'

vi.mock('../../../wailsjs/go/main/App', () => ({
  UploadFile: vi.fn(),
}))

function task(path: string): UploadTask {
  return { path, folderId: 'folder-1', name: '' }
}

// A promise whose settlement the test controls, standing in for one
// in-flight UploadFile call.
function deferred() {
  let resolve!: (id: string) => void
  let reject!: (e: unknown) => void
  const promise = new Promise<string>((res, rej) => { resolve = res; reject = rej })
  return { promise, resolve, reject }
}

beforeEach(() => {
  vi.mocked(UploadFile).mockReset()
})

describe('useUploadQueue', () => {
  it('starts empty: idle statuses, not running', () => {
    const { result } = renderHook(() => useUploadQueue())
    expect(result.current.running).toBe(false)
    expect(result.current.statuses.size).toBe(0)
    expect(result.current.statusOf('/a.pdf')).toEqual({ state: 'idle' })
  })

  it('uploads enqueued files one at a time, in order', async () => {
    const first = deferred()
    const second = deferred()
    vi.mocked(UploadFile).mockReturnValueOnce(first.promise).mockReturnValueOnce(second.promise)

    const { result } = renderHook(() => useUploadQueue())
    act(() => { result.current.enqueue([task('/a.pdf'), task('/b.pdf')]) })

    expect(result.current.running).toBe(true)
    expect(result.current.statusOf('/a.pdf')).toEqual({ state: 'uploading' })
    expect(result.current.statusOf('/b.pdf')).toEqual({ state: 'queued' })
    expect(UploadFile).toHaveBeenCalledTimes(1)
    expect(UploadFile).toHaveBeenCalledWith('/a.pdf', 'folder-1', '')

    await act(async () => { first.resolve('id-a') })
    expect(result.current.statusOf('/a.pdf')).toEqual({ state: 'done' })
    expect(result.current.statusOf('/b.pdf')).toEqual({ state: 'uploading' })

    await act(async () => { second.resolve('id-b') })
    expect(result.current.statusOf('/b.pdf')).toEqual({ state: 'done' })
    await waitFor(() => expect(result.current.running).toBe(false))
  })

  it('marks a failed file error with its message and moves on to the next', async () => {
    const first = deferred()
    const second = deferred()
    vi.mocked(UploadFile).mockReturnValueOnce(first.promise).mockReturnValueOnce(second.promise)

    const { result } = renderHook(() => useUploadQueue())
    act(() => { result.current.enqueue([task('/a.pdf'), task('/b.pdf')]) })

    await act(async () => { first.reject(new Error('quota exceeded')) })
    expect(result.current.statusOf('/a.pdf')).toEqual({ state: 'error', message: 'Error: quota exceeded' })
    expect(result.current.statusOf('/b.pdf')).toEqual({ state: 'uploading' })

    await act(async () => { second.resolve('id-b') })
    expect(result.current.statusOf('/b.pdf')).toEqual({ state: 'done' })
    await waitFor(() => expect(result.current.running).toBe(false))
  })

  it('appends tasks enqueued mid-run instead of starting a second worker', async () => {
    const first = deferred()
    const second = deferred()
    vi.mocked(UploadFile).mockReturnValueOnce(first.promise).mockReturnValueOnce(second.promise)

    const { result } = renderHook(() => useUploadQueue())
    act(() => { result.current.enqueue([task('/a.pdf')]) })
    act(() => { result.current.enqueue([task('/b.pdf')]) })

    // /b.pdf waits its turn: only /a.pdf's upload is in flight.
    expect(UploadFile).toHaveBeenCalledTimes(1)
    expect(result.current.statusOf('/b.pdf')).toEqual({ state: 'queued' })

    await act(async () => { first.resolve('id-a') })
    expect(result.current.statusOf('/b.pdf')).toEqual({ state: 'uploading' })
    await act(async () => { second.resolve('id-b') })
    await waitFor(() => expect(result.current.running).toBe(false))
  })

  it('skips tasks already queued or uploading', async () => {
    const first = deferred()
    vi.mocked(UploadFile).mockReturnValueOnce(first.promise)

    const { result } = renderHook(() => useUploadQueue())
    act(() => { result.current.enqueue([task('/a.pdf'), task('/b.pdf')]) })
    act(() => { result.current.enqueue([task('/a.pdf'), task('/b.pdf')]) })

    await act(async () => { first.resolve('id-a') })
    // Each file uploaded once despite the duplicate enqueue.
    await act(async () => {})
    expect(UploadFile).toHaveBeenCalledTimes(2)
  })

  it('re-enqueues a failed file when asked again (retry)', async () => {
    const first = deferred()
    const second = deferred()
    vi.mocked(UploadFile).mockReturnValueOnce(first.promise).mockReturnValueOnce(second.promise)

    const { result } = renderHook(() => useUploadQueue())
    act(() => { result.current.enqueue([task('/a.pdf')]) })
    await act(async () => { first.reject(new Error('boom')) })
    await waitFor(() => expect(result.current.running).toBe(false))

    act(() => { result.current.enqueue([task('/a.pdf')]) })
    expect(result.current.statusOf('/a.pdf')).toEqual({ state: 'uploading' })
    await act(async () => { second.resolve('id-a') })
    expect(result.current.statusOf('/a.pdf')).toEqual({ state: 'done' })
  })

  it('cancelRemaining lets the in-flight upload finish and returns queued files to idle', async () => {
    const first = deferred()
    vi.mocked(UploadFile).mockReturnValueOnce(first.promise)

    const { result } = renderHook(() => useUploadQueue())
    act(() => { result.current.enqueue([task('/a.pdf'), task('/b.pdf'), task('/c.pdf')]) })
    act(() => { result.current.cancelRemaining() })

    // Cancel doesn't abort the in-flight file.
    expect(result.current.statusOf('/a.pdf')).toEqual({ state: 'uploading' })

    await act(async () => { first.resolve('id-a') })
    expect(result.current.statusOf('/a.pdf')).toEqual({ state: 'done' })
    expect(result.current.statusOf('/b.pdf')).toEqual({ state: 'idle' })
    expect(result.current.statusOf('/c.pdf')).toEqual({ state: 'idle' })
    expect(UploadFile).toHaveBeenCalledTimes(1)
    await waitFor(() => expect(result.current.running).toBe(false))
  })

  it('can start a fresh run after a cancel', async () => {
    const first = deferred()
    const second = deferred()
    vi.mocked(UploadFile).mockReturnValueOnce(first.promise).mockReturnValueOnce(second.promise)

    const { result } = renderHook(() => useUploadQueue())
    act(() => { result.current.enqueue([task('/a.pdf'), task('/b.pdf')]) })
    act(() => { result.current.cancelRemaining() })
    await act(async () => { first.resolve('id-a') })
    await waitFor(() => expect(result.current.running).toBe(false))

    act(() => { result.current.enqueue([task('/b.pdf')]) })
    expect(result.current.statusOf('/b.pdf')).toEqual({ state: 'uploading' })
    await act(async () => { second.resolve('id-b') })
    expect(result.current.statusOf('/b.pdf')).toEqual({ state: 'done' })
  })

  it('reset clears all statuses and ignores uploads still in flight from before', async () => {
    const first = deferred()
    vi.mocked(UploadFile).mockReturnValueOnce(first.promise)

    const { result } = renderHook(() => useUploadQueue())
    act(() => { result.current.enqueue([task('/a.pdf'), task('/b.pdf')]) })
    act(() => { result.current.reset() })

    expect(result.current.running).toBe(false)
    expect(result.current.statuses.size).toBe(0)

    // The pre-reset in-flight upload settling must not resurrect its status.
    await act(async () => { first.resolve('id-a') })
    expect(result.current.statuses.size).toBe(0)
    expect(result.current.statusOf('/a.pdf')).toEqual({ state: 'idle' })
  })
})

