import { UploadFile } from '../../../wailsjs/go/main/App'

export type UploadStatus =
  | { state: 'idle' }
  | { state: 'queued' }
  | { state: 'uploading' }
  | { state: 'done' }
  | { state: 'error'; message: string }

// Shared instance so a miss has a stable identity for memoized consumers.
const IDLE: UploadStatus = { state: 'idle' }

// One file's upload job: which file, where it goes, and what it's called.
export interface UploadTask {
  path: string // LocalFile.path — the key upload status is tracked under
  folderId: string // effective Drive folder assignment
  name: string // Drive filename (LocalFile.name until step 4 adds renaming)
}

export interface UploadQueueHandle {
  statusOf: (path: string) => UploadStatus
  running: boolean
  started: boolean
  enqueue: (tasks: UploadTask[]) => void
  retry: (path: string) => void
  retryFailed: () => void
  cancelRemaining: () => void
  reset: () => void
}

// Tracks per-file upload status and runs a sequential (concurrency = 1)
// worker over enqueued tasks. Group-level status is never stored — callers
// derive it by rolling up file statuses via flattenFiles. Resolving each
// file's effective Drive assignment into an UploadTask is likewise the
// caller's job; the queue only executes tasks. Failed tasks are retained,
// so retry()/retryFailed() re-send the exact destination and name that
// failed without the caller re-resolving assignments.
//
// enqueue() during an active run appends to it; tasks already queued or
// uploading are skipped. cancelRemaining() stops starting new files without
// aborting the in-flight one. started stays true from the first enqueue()
// until reset(), which discards everything, for when a new root folder
// replaces the tree.
export function useUploadQueue(): UploadQueueHandle {
  const [statuses, setStatuses] = useState<Map<string, UploadStatus>>(new Map())
  const [running, setRunning] = useState(false)
  const [started, setStarted] = useState(false)

  // The worker and enqueue read these between awaits, where state would be
  // stale. queueRef[0] is the in-flight task while running (it's removed
  // once it settles); the queue is empty whenever the worker is idle.
  const queueRef = useRef<UploadTask[]>([])
  const runningRef = useRef(false)
  const failedRef = useRef<Map<string, UploadTask>>(new Map())
  // Bumped by reset() so a worker (and its in-flight upload) from before the
  // reset can't write statuses into the fresh queue when it settles.
  const generationRef = useRef(0)

  const setStatus = (path: string, status: UploadStatus) => {
    setStatuses(prev => new Map(prev).set(path, status))
  }

  const run = async () => {
    const generation = generationRef.current
    runningRef.current = true
    setRunning(true)

    while (queueRef.current.length > 0) {
      const task = queueRef.current[0]
      setStatus(task.path, { state: 'uploading' })
      let status: UploadStatus
      try {
        await UploadFile(task.path, task.folderId, task.name)
        status = { state: 'done' }
      } catch (e) {
        status = { state: 'error', message: String(e) }
      }
      if (generation !== generationRef.current) return
      queueRef.current.shift()
      if (status.state === 'error') failedRef.current.set(task.path, task)
      else failedRef.current.delete(task.path)
      setStatus(task.path, status)
    }

    runningRef.current = false
    setRunning(false)
  }

  const enqueue = useCallback((tasks: UploadTask[]) => {
    // Skip anything already queued or in flight.
    const fresh = tasks.filter(task => !queueRef.current.some(t => t.path === task.path))
    if (fresh.length === 0) return
    queueRef.current.push(...fresh)
    setStatuses(prev => {
      const next = new Map(prev)
      for (const task of fresh) next.set(task.path, { state: 'queued' })
      return next
    })
    setStarted(true)
    if (!runningRef.current) void run()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const retry = useCallback((path: string) => {
    const task = failedRef.current.get(path)
    if (task) enqueue([task])
  }, [enqueue])

  const retryFailed = useCallback(() => {
    enqueue([...failedRef.current.values()])
  }, [enqueue])

  const cancelRemaining = useCallback(() => {
    // Everything behind the in-flight queueRef[0] was never attempted.
    const dropped = queueRef.current.splice(1)
    if (dropped.length === 0) return
    setStatuses(prev => {
      const next = new Map(prev)
      for (const task of dropped) next.set(task.path, IDLE)
      return next
    })
  }, [])

  const reset = useCallback(() => {
    generationRef.current++
    queueRef.current = []
    runningRef.current = false
    failedRef.current = new Map()
    setStatuses(new Map())
    setRunning(false)
    setStarted(false)
  }, [])

  const statusOf = (path: string): UploadStatus => statuses.get(path) ?? IDLE

  return { statusOf, running, started, enqueue, retry, retryFailed, cancelRemaining, reset }
}

