import { useState, useCallback, useRef } from 'react'
import { UploadFile } from '../../../wailsjs/go/main/App'

export type UploadStatus =
  | { state: 'idle' }
  | { state: 'queued' }
  | { state: 'uploading' }
  | { state: 'done' }
  | { state: 'error'; message: string }

// One file's upload job: which file, where it goes, and what it's called.
export interface UploadTask {
  path: string // LocalFile.path — the key upload status is tracked under
  folderId: string // effective Drive folder assignment
  name: string // Drive filename; '' lets the backend default to the base name
}

export interface UploadQueueHandle {
  statuses: Map<string, UploadStatus>
  statusOf: (path: string) => UploadStatus
  running: boolean
  enqueue: (tasks: UploadTask[]) => void
  cancelRemaining: () => void
  reset: () => void
}

// Tracks per-file upload status and runs a sequential (concurrency = 1)
// worker over enqueued tasks. Group-level status is never stored — callers
// derive it by rolling up file statuses via flattenFiles. Resolving each
// file's effective Drive assignment into an UploadTask is likewise the
// caller's job; the queue only executes tasks.
//
// enqueue() during an active run appends to it (used by per-file Retry);
// tasks already queued or uploading are skipped. cancelRemaining() stops
// starting new files without aborting the in-flight one; never-attempted
// tasks return to idle. reset() discards everything, for when a new root
// folder replaces the tree.
export function useUploadQueue(): UploadQueueHandle {
  const [statuses, setStatuses] = useState<Map<string, UploadStatus>>(new Map())
  const [running, setRunning] = useState(false)

  // The async worker reads these between awaits, where state would be stale.
  const statusesRef = useRef<Map<string, UploadStatus>>(new Map())
  const queueRef = useRef<UploadTask[]>([])
  const runningRef = useRef(false)
  const cancelledRef = useRef(false)
  // Bumped by reset() so a worker (and its in-flight upload) from before the
  // reset can't write statuses into the fresh queue when it settles.
  const generationRef = useRef(0)

  const setStatus = (path: string, status: UploadStatus) => {
    statusesRef.current = new Map(statusesRef.current).set(path, status)
    setStatuses(statusesRef.current)
  }

  const run = async () => {
    const generation = generationRef.current
    runningRef.current = true
    setRunning(true)

    while (queueRef.current.length > 0 && !cancelledRef.current) {
      const task = queueRef.current.shift()!
      setStatus(task.path, { state: 'uploading' })
      let status: UploadStatus
      try {
        await UploadFile(task.path, task.folderId, task.name)
        status = { state: 'done' }
      } catch (e) {
        status = { state: 'error', message: String(e) }
      }
      if (generation !== generationRef.current) return
      setStatus(task.path, status)
    }

    // Anything still queued after a cancel was never attempted.
    for (const task of queueRef.current) setStatus(task.path, { state: 'idle' })
    queueRef.current = []
    cancelledRef.current = false
    runningRef.current = false
    setRunning(false)
  }

  const enqueue = useCallback((tasks: UploadTask[]) => {
    const fresh = tasks.filter(task => {
      const state = statusesRef.current.get(task.path)?.state
      return state !== 'queued' && state !== 'uploading'
    })
    if (fresh.length === 0) return
    queueRef.current.push(...fresh)
    for (const task of fresh) setStatus(task.path, { state: 'queued' })
    if (!runningRef.current) void run()
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  const cancelRemaining = useCallback(() => {
    if (runningRef.current) cancelledRef.current = true
  }, [])

  const reset = useCallback(() => {
    generationRef.current++
    queueRef.current = []
    cancelledRef.current = false
    runningRef.current = false
    statusesRef.current = new Map()
    setStatuses(statusesRef.current)
    setRunning(false)
  }, [])

  const statusOf = useCallback(
    (path: string): UploadStatus => statuses.get(path) ?? { state: 'idle' },
    [statuses],
  )

  return { statuses, statusOf, running, enqueue, cancelRemaining, reset }
}

