import { describe, it, expect, vi } from 'vitest'
import { act, renderHook, waitFor } from '@testing-library/react'
import { useFileTree, flattenFiles, LocalFile, LocalFileGroup } from './useFileTree'
import { PickFolder, ScanLocalRoot } from '../../../wailsjs/go/main/App'
import { basename } from '../../utils'

vi.mock('../../../wailsjs/go/main/App', () => ({
  PickFolder: vi.fn(),
  ScanLocalRoot: vi.fn(),
}))

function file(path: string): LocalFile {
  return { path, name: path.split('/').pop()!, sizeBytes: 1, isPdf: true, pageCount: 1, corrupt: false }
}

function group(name: string, files: LocalFile[], subgroups: LocalFileGroup[] = []): LocalFileGroup {
  return { name, files, subgroups }
}

describe('flattenFiles', () => {
  it('returns an empty list for a group with no files anywhere', () => {
    expect(flattenFiles(group('root', [], [group('empty', [])]))).toEqual([])
  })

  it('lists own files before subgroup files, recursing through nesting', () => {
    const tree = group('root', [file('/r/a.pdf')], [
      group('x', [file('/r/x/b.pdf')], [group('y', [file('/r/x/y/c.pdf')])]),
      group('z', [file('/r/z/d.pdf')]),
    ])
    expect(flattenFiles(tree).map(f => f.path)).toEqual([
      '/r/a.pdf', '/r/x/b.pdf', '/r/x/y/c.pdf', '/r/z/d.pdf',
    ])
  })
})

describe('useFileTree', () => {
